insert into opportunities (slug, title, type, sponsor, summary, topics, opens_at, closes_at, recurrence, mission_need, eligibility, requirements, submission_instructions, documents, contact_email, external_url, status) values ('solutions-marketplace-collection', 'Tradewinds Solutions Marketplace — Monthly Collection Period', 'marketplace-collection', 'CDAO · Tradewinds', 'The Marketplace''s ongoing solicitation. Submit a five-minute video pitch of your AI, digital or data-analytics solution for peer/SME assessment in this month''s cycle.', array['AI/ML', 'Data & Analytics', 'Digital']::text[], null, null, 'monthly', 'Department of War organizations need a fast, competitive route to mission-ready AI, digital and data-analytics capabilities. Solutions assessed as awardable are placed in the Marketplace, where government buyers can discover them and move to award.', 'Open to U.S. businesses, non-traditional defense contractors and academia, and to certain foreign entities. Confirm current eligibility terms in the official solicitation before submitting.', array['A video pitch no longer than 5:00 minutes — longer submissions are not assessed', 'A solution-provider account on the Tradewinds submission portal', 'Upload completed by 12:00 pm Eastern on the last day of the month to enter that month''s assessment']::text[], 'Create or sign in to your solution-provider account, upload your video pitch and supporting information, and submit before the monthly deadline. Submissions assessed as non-awardable receive feedback and may be revised and resubmitted in a later period.', '[{"label":"I''m Awardable — Now What? (PDF)","url":"https://storage.tradewindai.com/pdfs/Info-Sheet-Im-Awardable-Now-What.pdf"}]'::jsonb, 'success@tradewindai.com', 'https://www.tradewindai.com/tw-marketplace', 'published') on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, status, sort_order) values ('test-and-evaluation', 'AI Test & Evaluation Services BPA', 'T&E', 'Blanket Purchase Agreement', 'active', 'Test technology, tools and services for AI and autonomy.', 'The CDAO Test and Evaluation Services Blanket Purchase Agreement meets Department needs for test technology and tools for AI and autonomy applications. CDAO manages the BPA in partnership with its prime contractors and in coordination with Army Contracting Command – Rock Island (ACC-RI).', array['Test technology and tools', 'Data set development and curation', 'Test harness development', 'Model output analysis', 'Test planning, documentation and reporting', 'Targeted T&E and independent verification & validation (IV&V)', 'Operational T&E', 'Human factors and user-acceptance T&E']::text[], 'Open for ordering to all agencies of the U.S. Government in support of AI test and evaluation.', array['Define the T&E requirement and confirm it falls within BPA scope', 'Contact the Tradewinds team to discuss scope and ordering', 'Develop the order package with ACC-RI', 'Compete among BPA holders and award the call order']::text[], 'Active — accepting orders', '[{"label":"T&E Services one-pager (AI.mil)","url":"https://www.ai.mil/docs/TE_One_Pager.pdf"}]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, null, array['Current BPA holder list', 'Ordering period of performance']::text[], 'published', 0) on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, status, sort_order) values ('draid', 'Data Readiness for AI Development', 'DRAID', 'Basic Ordering Agreement', 'pending-confirmation', 'Preparing data so it is ready for AI development.', 'DRAID was established under the Joint Artificial Intelligence Center (JAIC), a CDAO predecessor organization, to provide data-readiness services that prepare data for AI development.', array['Data readiness and preparation services for AI development']::text[], 'Awaiting confirmation from the program office.', array['Contact the Tradewinds vehicles team to confirm current ordering availability']::text[], 'Current ordering status awaiting confirmation', '[]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, 'Established under JAIC. Historical information is shown separately from current ordering guidance.', array['Detailed scope', 'Eligible users', 'Ordering instructions', 'Agreement holders', 'Official documents']::text[], 'published', 1) on conflict (slug) do nothing;
insert into contract_vehicles (slug, name, short_name, vehicle_type, vehicle_status, tagline, overview, scope, eligible_users, ordering_process, availability, documents, holders, contacts, historical_notes, pending_fields, status, sort_order) values ('ai-talent-2', 'AI Talent 2.0', 'AI Talent 2.0', 'Contract vehicle', 'pending-confirmation', 'Access to AI technical talent and services.', 'AI Talent 2.0 provides access to AI technical expertise. Detailed scope, ordering procedures and holder information will be published here once approved by the program office.', array['AI and data technical talent services']::text[], 'Awaiting confirmation from the program office.', array['Contact the Tradewinds vehicles team for current ordering guidance']::text[], 'Awaiting approved content', '[]'::jsonb, null, '[{"label":"Tradewinds vehicles team","email":"success@tradewindai.com"}]'::jsonb, null, array['Vehicle type', 'Detailed scope', 'Eligible users', 'Ordering instructions', 'Holders', 'Official documents']::text[], 'published', 2) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('what-is-the-marketplace', 'What is the Tradewinds Solutions Marketplace?', 'The Tradewinds Solutions Marketplace is a digital repository of post-competition, readily awardable pitch videos for AI, digital and data-analytics solutions. It gives government buyers a single place to discover solutions that have already been assessed through a competitive process.', 'Marketplace', array['all']::text[], 'published', 0) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('what-does-awardable-mean', 'What does “awardable” mean?', 'A solution is designated awardable when its video pitch has been assessed by a peer and subject-matter-expert panel and found to meet the Marketplace''s criteria. Awardable solutions are placed in the Marketplace, where eligible government customers can discover them and pursue an award.
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('who-can-view', 'Who can view solutions in the Marketplace?', 'Only government users with a .gov or .mil email address are given access to view the pitch-video library. Government users can search by video title or company name once signed in.', 'Government Access', array['government']::text[], 'published', 2) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('provider-account-access', 'Can I see other companies'' solutions with a solution-provider account?', 'No. Solution-provider accounts are for submitting pitch videos and managing your own submissions. They do not provide access to view other solutions.', 'Government Access', array['industry']::text[], 'published', 3) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('video-length', 'How long can my pitch video be?', 'Video pitches must not exceed five minutes (5:00). Submissions that exceed the length limitation are not assessed.', 'Submissions', array['industry']::text[], 'published', 4) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('submission-deadline', 'When are submissions due?', 'Submissions are collected in monthly periods. Upload your video by 12:00 pm Eastern on the last day of the month to be included in that month''s assessment cycle.', 'Submissions', array['industry']::text[], 'published', 5) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('not-awardable', 'What happens if my solution is not determined awardable?', 'You will receive feedback from the assessment. You may revise your submission and resubmit in a later collection period.', 'Submissions', array['industry']::text[], 'published', 6) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('who-can-submit', 'Who can submit a solution?', 'The Marketplace accepts submissions from U.S. businesses, non-traditional defense contractors and academia, as well as certain foreign entities. Review the current solicitation for the authoritative eligibility terms.', 'Submissions', array['industry']::text[], 'published', 7) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('after-awardable', 'I''m awardable. What happens next?', 'Awardable status makes your solution discoverable to government buyers. Review the “I''m Awardable — Now What?” information sheet for guidance on approved language, use of the Awardable graphic and engaging with buyers.', 'Acquisition', array['industry']::text[], 'published', 8) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('how-buyers-award', 'How does a government buyer make an award?', 'After identifying an awardable solution, the buying activity works with its contracting office to select an appropriate award mechanism and negotiate terms with the vendor. Contact the Tradewinds team for acquisition support.', 'Acquisition', array['government']::text[], 'published', 9) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('who-runs-tradewinds', 'Who runs Tradewinds?', 'Tradewinds is housed in the Chief Digital and Artificial Intelligence Office (CDAO). The Applied Research Institute (ARI) serves as the Marketplace manager.', 'General', array['all']::text[], 'published', 10) on conflict (slug) do nothing;
insert into faqs (slug, question, answer, category, audiences, status, sort_order) values ('contact', 'How do I contact the Tradewinds team?', 'For program and acquisition questions email success@tradewindai.com. For account and technical issues email support@tradewindai.com.', 'General', array['all']::text[], 'published', 11) on conflict (slug) do nothing;
insert into resources (slug, title, kind, audiences, summary, url, date, status) values ('im-awardable-now-what', 'I''m Awardable — Now What?', 'guide', array['industry']::text[], 'Next steps after your solution is determined awardable: approved language, the Awardable graphic and engaging buyers.', 'https://storage.tradewindai.com/pdfs/Info-Sheet-Im-Awardable-Now-What.pdf', null, 'published') on conflict (slug) do nothing;
insert into resources (slug, title, kind, audiences, summary, url, date, status) values ('customer-handbook', 'Solutions Marketplace Customer Handbook (v1.2)', 'document', array['government']::text[], 'How government customers access the Marketplace, discover solutions and proceed to award.', 'https://storage.tradewindai.com/pdfs/Tradewinds-Solutions-Marketplace-Customer-Handbook-v1.2-Aug-2023_2023-08-30-143746_tawp.pdf', '2023-08-30', 'published') on conflict (slug) do nothing;
